insert into "readiness_pillars" ("pillar_id", "created_at", "pillar_description", "pillar_name", "pillar_order", "pillar_weightage", "red_flag_note", "red_flag_threshold", "score_bands", "stage_behaviour", "updated_at", "what_falls_under") values ('1', '2026-07-10 11:15:56.284048+00', 'Measures the founder as a person — psychological state, self-awareness, resilience, motivation depth, decision-making quality, and capacity to lead under pressure. The single most important variable in startup success.', 'Founder Readiness', '1', '25.00', 'A score below 35% in this pillar triggers Section H (Psychological State Note) in the Founder Clarity Report regardless of all other scores. The report will acknowledge the emotional reality before presenting any business diagnosis.', '35.00', '[{"level": "Critical Gap", "range_max": 35, "range_min": 0, "description": "Right now you are carrying more than you can hold. That might be exhaustion, real fear about this failing, feeling alone in it, or not being sure who you are outside this business. Whatever it is, it comes first. Fixing things in the business will not shift much until this does."}, {"level": "Needs Attention", "range_max": 55, "range_min": 36, "description": "You have the drive. You are also showing the strain — working too much, no line between work and the rest of your life, decisions made in a rush, or doubting yourself even when you are doing well. You can keep moving, but only so far until you build a pace you can actually keep up."}, {"level": "Developing", "range_max": 75, "range_min": 56, "description": "You know yourself reasonably well, you are motivated, and you hold up under pressure. There are some blind spots and some stress patterns, but neither is stopping you growing. This is where most founders are early on."}, {"level": "Strong", "range_max": 100, "range_min": 76, "description": "You know yourself well, you want this for your own reasons, you stay steady when things get hard, and you bounce back. You ask for feedback, you decide deliberately, and you work at a pace you can keep. That is rare, and it is a real advantage."}]', '[{"stage": "Ideation (Stage 1)", "stage_id": 1, "description": "Motivation clarity and idea conviction are the primary measures. Most founders at this stage score low here because the real psychological challenge of building has not yet begun.", "stage_group": "Stage 0"}, {"stage": "Validation to Prototype/MVP (Stages 2-3)", "stage_id": "2-3", "description": "Resilience and self-awareness become critical. The gap between excitement and the grind of execution reveals itself here. Burnout Stage 1 is most common in this range.", "stage_group": "Stage 0→1"}, {"stage": "Early Traction to Growth/Scaling (Stages 4-5)", "stage_id": "4-5", "description": "Delegation anxiety and identity fusion become the key issues — founders who cannot let go of control create the ceiling for their company. Decision-making quality under scale pressure is tested.", "stage_group": "Spans Stage 0→1 and Stage 1→10+"}, {"stage": "Expansion to Maturity (Stages 6-7)", "stage_id": "6-7", "description": "Leadership identity and CEO evolution. The founder must shift from doer to architect. Those who cannot make this transition personally will stall the business regardless of market opportunity.", "stage_group": "Stage 1→10+"}, {"stage": "Exit (Stage 8)", "stage_id": 8, "description": "Legacy mindset, succession thinking, and sustained purpose. Burnout is a risk even here — founders who built too much of their identity into the company struggle at this stage.", "stage_group": "Stage 1→10+"}]', '2026-07-26 05:27:23.650751+00', '["Intrinsic motivation — why they are building and how deep that drive goes", "Self-awareness — whether they know their strengths, blind spots, and triggers", "Emotional regulation — how they process setbacks, rejection, and uncertainty", "Decision-making quality — how they make big decisions and learn from them", "Resilience and persistence — whether they can sustain effort through long difficult periods", "Identity and founder psychology — imposter syndrome, fear of failure, perfectionism, burnout", "Learning orientation — whether they seek feedback and update their beliefs", "Support structures — whether they have mentors, peers, or a team to lean on"]') on conflict do nothing;
insert into "readiness_pillars" ("pillar_id", "created_at", "pillar_description", "pillar_name", "pillar_order", "pillar_weightage", "red_flag_note", "red_flag_threshold", "score_bands", "stage_behaviour", "updated_at", "what_falls_under") values ('2', '2026-07-10 11:15:56.284048+00', 'Measures how well the founder understands the problem they are solving, who they are solving it for, and whether there is real evidence of demand. Covers customer discovery, ICP definition, competitive awareness, value proposition, and go-to-market strategy.', 'Market Clarity', '2', '20.00', 'Scores below 35% in Market Clarity combined with Stage 3 or above is a critical signal — the founder has been building without validating. This combination triggers a deep-dive in the Idea & Validation and GTM diagnostic categories.', '35.00', '[{"level": "Critical Gap", "range_max": 35, "range_min": 0, "description": "You are building for a customer you have imagined, solving a problem you have assumed, with nothing yet to show either is real. You cannot say precisely who this is for, you have not sat down with customers, or you think everyone is a customer. This is the riskiest place to be — time and money are going into a guess."}, {"level": "Needs Attention", "range_max": 55, "range_min": 36, "description": "You have asked around, but not deeply enough. You have a rough sense of who this is for without the specifics. How you plan to reach them is still vague. People may have told you they liked the idea, but you cannot point to anything showing they would pay for it."}, {"level": "Developing", "range_max": 75, "range_min": 56, "description": "You know who this is for, you have had real conversations with customers, and you understand who else is in the market. You have a plan for reaching people, even if it is not tested yet. You can say clearly what you are worth to them."}, {"level": "Strong", "range_max": 100, "range_min": 76, "description": "You know this market properly and you have checked it. You can name your ideal customer exactly, you have proof people want this rather than opinions, you know why someone would switch to you, and how you reach them is built on real numbers rather than assumptions."}]', '[{"stage": "Ideation (Stage 1)", "stage_id": 1, "description": "Problem and customer hypothesis are the primary measures. At this stage lack of market clarity is normal and expected — the goal is identifying it early so it gets addressed before building begins.", "stage_group": "Stage 0"}, {"stage": "Validation to Prototype/MVP (Stages 2-3)", "stage_id": "2-3", "description": "Customer discovery must happen here. Founders who skip this and build on assumptions surface in diagnosis with strong product scores but weak market clarity — a common and costly pattern.", "stage_group": "Stage 0→1"}, {"stage": "Early Traction to Growth/Scaling (Stages 4-5)", "stage_id": "4-5", "description": "ICP precision and channel consistency become critical. Early GTM approaches that worked on hustle need to become systematic. Founders who have not refined their ICP hit a ceiling here.", "stage_group": "Spans Stage 0→1 and Stage 1→10+"}, {"stage": "Expansion to Maturity (Stages 6-7)", "stage_id": "6-7", "description": "Market expansion strategy and new segment entry. The original ICP may be saturating and the founder needs clarity on adjacent markets, international expansion, or product-line extension.", "stage_group": "Stage 1→10+"}, {"stage": "Exit (Stage 8)", "stage_id": 8, "description": "Category creation and market leadership. The founder is no longer finding a market — they are shaping one.", "stage_group": "Stage 1→10+"}]', '2026-07-26 05:27:23.650751+00', '["Problem clarity — can the founder articulate the pain clearly and specifically", "Customer discovery — have they spoken to real potential customers outside their network", "Ideal Customer Profile (ICP) — is the target customer specific and well-defined", "Demand validation — is there evidence that people want this, not just believe they do", "Competitive awareness — do they know what alternatives exist and why theirs is better", "Value proposition — can they articulate why a customer would switch to their solution", "Go-to-market strategy — do they have a structured path to reaching and acquiring customers", "Positioning — do they know where they sit in the market and how to communicate that"]') on conflict do nothing;
insert into "readiness_pillars" ("pillar_id", "created_at", "pillar_description", "pillar_name", "pillar_order", "pillar_weightage", "red_flag_note", "red_flag_threshold", "score_bands", "stage_behaviour", "updated_at", "what_falls_under") values ('3', '2026-07-10 11:15:56.284048+00', 'Measures how deliberately the founder builds and manages the commercial engine of their business. Covers pricing strategy, sales process, pipeline management, unit economics, customer retention, revenue predictability, and financial planning.', 'Revenue Maturity', '3', '20.00', 'A founder at Stage 4 or above with a Revenue Maturity score below 40% is a high-priority signal. At that stage, revenue systems should exist. Their absence indicates the business may be surviving on funding or founder relationships rather than commercial viability.', '40.00', '[{"level": "Critical Gap", "range_max": 35, "range_min": 0, "description": "You have no set way of selling, you do not know what it costs you to serve a customer, you price on gut feel, and you cannot tell what next month brings. If money is coming in, it is luck more than design. Cash may be going out faster than you have noticed."}, {"level": "Needs Attention", "range_max": 55, "range_min": 36, "description": "You are making sales, but not in a way you could repeat on purpose. You charge too little, you do not track who might buy next, and you have never worked out what each sale actually earns you. Growth is happening, and it rests entirely on how hard you push."}, {"level": "Developing", "range_max": 75, "range_min": 56, "description": "You have a way of selling that you follow, a sensible view on price, and some grip on what each customer costs and earns. Money coming in is growing and you can roughly see it coming. You watch whether customers stay. You are moving from reacting to planning."}, {"level": "Strong", "range_max": 100, "range_min": 76, "description": "You run revenue like a system. You know who might buy next, you price on the value you give, each sale earns well, customers stay, and you keep your numbers up to date. You can see what is coming, and you know exactly what has to happen to grow it."}]', '[{"stage": "Ideation (Stage 1)", "stage_id": 1, "description": "Revenue Maturity is not expected at this stage. The score here measures intent — whether the founder has thought about how they will make money and for whom. Pre-revenue is normal and fine.", "stage_group": "Stage 0"}, {"stage": "Validation to Prototype/MVP (Stages 2-3)", "stage_id": "2-3", "description": "First revenue and initial sales learnings. The founder should be actively selling, not waiting for the product to be perfect. Low scores here indicate sales avoidance — one of the most common founder blind spots.", "stage_group": "Stage 0→1"}, {"stage": "Early Traction to Growth/Scaling (Stages 4-5)", "stage_id": "4-5", "description": "Unit economics become critical. Revenue growing without understanding LTV:CAC or gross margin is a ticking clock. This is where many Indian startups discover they have been growing unprofitably.", "stage_group": "Spans Stage 0→1 and Stage 1→10+"}, {"stage": "Expansion to Maturity (Stages 6-7)", "stage_id": "6-7", "description": "Revenue operations and predictability. The sales motion must be scalable — repeatable by people who are not the founder. Revenue retention (NRR) becomes more important than acquisition.", "stage_group": "Stage 1→10+"}, {"stage": "Exit (Stage 8)", "stage_id": 8, "description": "Capital efficiency and sustainable growth. The question shifts from how do we grow to how do we grow without destroying value in the process.", "stage_group": "Stage 1→10+"}]', '2026-07-26 05:27:23.650751+00', '["Sales process — is there a structured, repeatable process for acquiring customers", "Pipeline management — does the founder know what is in their pipeline and what will close", "Pricing strategy — is pricing based on value and data, not gut feel or cost-plus", "Unit economics — does the founder know their CAC, LTV, gross margin, and payback period", "Revenue retention — are customers staying and expanding, or churning", "Revenue predictability — is revenue recurring, contractual, or entirely project-based", "Financial planning — does the founder have a financial model and cash flow forecast", "Revenue model fit — does the revenue model match the business and market reality"]') on conflict do nothing;
insert into "readiness_pillars" ("pillar_id", "created_at", "pillar_description", "pillar_name", "pillar_order", "pillar_weightage", "red_flag_note", "red_flag_threshold", "score_bands", "stage_behaviour", "updated_at", "what_falls_under") values ('4', '2026-07-10 11:15:56.284048+00', 'Measures the founder''s ability to build the right thing and build it well. Covers product-market fit signals, development discipline, user feedback loops, prioritisation rigour, operational systems, and execution consistency.', 'Product & Execution', '4', '15.00', 'A score below 35% in Product & Execution at Stage 3 or above signals that the founder has been building without a reliable feedback loop or execution system. This is a critical gap that blocks all other growth.', '35.00', '[{"level": "Critical Gap", "range_max": 35, "range_min": 0, "description": "What you are making is either not built, not working, or not actually useful to anyone yet. Getting things done is chaotic — nothing has a set way of being done, every day is firefighting, and all of it runs through you. At this point the business cannot grow even if you know your market and the money is coming in."}, {"level": "Needs Attention", "range_max": 55, "range_min": 36, "description": "What you make works, but it breaks easily. You do hear from customers, but only by chance rather than by design. What you work on next is decided by whatever is loudest. Things get done because people push hard, not because there is a way of doing them. The shortcuts are piling up."}, {"level": "Developing", "range_max": 75, "range_min": 56, "description": "What you make is genuinely useful and reliable enough. You have a way of hearing from real customers. There is some order to what you work on next. The main jobs have a set way of being done. Your team can get on with things without you in every decision."}, {"level": "Strong", "range_max": 100, "range_min": 76, "description": "People clearly want what you make. You build carefully, using what customers and the numbers tell you. Things get done through the way you work, not through heroics. You catch quality problems before customers do. You know what you are building next and why."}]', '[{"stage": "Ideation (Stage 1)", "stage_id": 1, "description": "Execution is about idea development and prototyping. Low scores are expected and acceptable. The signal being measured is whether the founder understands the difference between building and validating.", "stage_group": "Stage 0"}, {"stage": "Validation to Prototype/MVP (Stages 2-3)", "stage_id": "2-3", "description": "MVP quality and feedback loop discipline. Founders who build too much too fast without talking to users surface here with low product maturity despite high engineering effort. The MVP trap is most common at Stage 2.", "stage_group": "Stage 0→1"}, {"stage": "Early Traction to Growth/Scaling (Stages 4-5)", "stage_id": "4-5", "description": "Product-market fit must be demonstrated here. Execution systems and quality management become critical as the team grows beyond the founder''s direct oversight.", "stage_group": "Spans Stage 0→1 and Stage 1→10+"}, {"stage": "Expansion to Maturity (Stages 6-7)", "stage_id": "6-7", "description": "Product operations and platform thinking. The product must now serve multiple customer segments without custom engineering for each. Architecture decisions made in earlier stages become constraints here.", "stage_group": "Stage 1→10+"}, {"stage": "Exit (Stage 8)", "stage_id": 8, "description": "Product portfolio management and innovation pipeline. The original product is mature — the challenge is staying relevant while managing what exists.", "stage_group": "Stage 1→10+"}]', '2026-07-26 05:27:23.650751+00', '["Product-market fit signals — are users getting real value and staying", "Build discipline — does the founder avoid feature bloat and build the minimum valuable thing", "Feedback loops — are real users informing product decisions regularly", "Prioritisation — does the team know what to build next and why", "Technical quality — is the product stable, scalable, and maintainable", "Operational systems — are there processes, SOPs, and tools that enable consistent delivery", "Execution velocity — can the team ship and iterate fast enough to learn", "Quality management — does the team catch problems before customers do"]') on conflict do nothing;
insert into "readiness_pillars" ("pillar_id", "created_at", "pillar_description", "pillar_name", "pillar_order", "pillar_weightage", "red_flag_note", "red_flag_threshold", "score_bands", "stage_behaviour", "updated_at", "what_falls_under") values ('5', '2026-07-10 11:15:56.284048+00', 'Measures the founder''s ability to build, lead, and retain the team needed to execute their vision. Covers co-founder dynamics, hiring quality, delegation maturity, communication culture, accountability systems, and the founder''s evolution from operator to leader.', 'Team & Leadership', '5', '10.00', 'A score below 35% in Team & Leadership at Stage 4 or above is a serious signal. By Stage 4, the founder cannot do everything themselves. A team that is dysfunctional or misaligned at this stage will cap the entire company''s growth regardless of how strong the other pillars are.', '35.00', '[{"level": "Critical Gap", "range_max": 35, "range_min": 0, "description": "Your team is pulling apart, pulling in different directions, or is not really there yet. There may be a falling-out with a co-founder. You may be checking everything yourself, or have the wrong people in the jobs that matter. People are leaving, or about to. When this is where things stand, it is usually the hidden reason everything else moves slowly."}, {"level": "Needs Attention", "range_max": 55, "range_min": 36, "description": "The team works, but only just. You are still doing too much yourself. Handing things over feels uncomfortable. Some important jobs are held by people who are not quite right for them, and that is being worked around. Nobody is quite sure how things get communicated. Everyone works hard, not always towards the same thing."}, {"level": "Developing", "range_max": 75, "range_min": 56, "description": "People are reasonably clear on who does what and what matters most. You are genuinely starting to hand things over. There is some sense of who is answerable for what. People feel able to speak up. There are still gaps in the team, but you are pointed the right way."}, {"level": "Strong", "range_max": 100, "range_min": 76, "description": "Your team is good at what they do, pointed the same way, and able to get on without you in every conversation. You hire carefully. You genuinely hand things over. People can say hard things to each other and change course quickly. You are growing as a leader while the business grows."}]', '[{"stage": "Ideation (Stage 1)", "stage_id": 1, "description": "Team is usually just the founder. This pillar measures co-founder selection thinking, awareness of skill gaps, and whether the founder knows what kind of people they need to recruit.", "stage_group": "Stage 0"}, {"stage": "Validation to Prototype/MVP (Stages 2-3)", "stage_id": "2-3", "description": "First hires and co-founder dynamics are tested. Early hiring mistakes are common and recoverable. The key signal is whether the founder is hiring for skill fit or emotional comfort.", "stage_group": "Stage 0→1"}, {"stage": "Early Traction to Growth/Scaling (Stages 4-5)", "stage_id": "4-5", "description": "Delegation becomes the critical test. Founders who cannot let go create bottlenecks that limit the entire company''s pace. Manager development and accountability systems become essential.", "stage_group": "Spans Stage 0→1 and Stage 1→10+"}, {"stage": "Expansion to Maturity (Stages 6-7)", "stage_id": "6-7", "description": "Organisational design and leadership pipeline. The founder is now managing managers. The original team that built the company may not be the right team to scale it — this is one of the most difficult personal realities a founder faces.", "stage_group": "Stage 1→10+"}, {"stage": "Exit (Stage 8)", "stage_id": 8, "description": "Succession planning and institutional culture. The leader is building something that can outlast their direct involvement.", "stage_group": "Stage 1→10+"}]', '2026-07-26 05:27:23.650751+00', '["Co-founder alignment — do co-founders have complementary skills, clear roles, and shared vision", "Hiring quality — are people hired for demonstrated ability or familiarity and hope", "Delegation — can the founder let go of tasks and trust others to execute", "Communication — does the team have clarity on priorities, context, and expectations", "Accountability — are there systems for tracking commitments and addressing gaps", "Culture — is the work environment one where people can do their best work and speak honestly", "Conflict resolution — are disagreements addressed constructively or avoided until they explode", "Leadership evolution — is the founder growing as a leader as the company grows"]') on conflict do nothing;
insert into "readiness_pillars" ("pillar_id", "created_at", "pillar_description", "pillar_name", "pillar_order", "pillar_weightage", "red_flag_note", "red_flag_threshold", "score_bands", "stage_behaviour", "updated_at", "what_falls_under") values ('6', '2026-07-10 11:15:56.284048+00', 'Measures whether the founder has a coherent, defensible plan for where they are going and how they will get there. Covers vision articulation, goal quality, decision-making frameworks, competitive strategy, capital planning, and the ability to prioritise ruthlessly.', 'Strategic Clarity', '6', '10.00', 'A score below 35% in Strategic Clarity at Stage 4 or above is a serious signal. At earlier stages low strategic clarity is acceptable and normal. At Stage 4 and beyond, the absence of strategic direction means the business is growing without a compass — every new opportunity creates noise rather than momentum.', '35.00', '[{"level": "Critical Gap", "range_max": 35, "range_min": 0, "description": "You are working without a clear direction. You react to what comes up and chase whatever appears, with no way of deciding what deserves your time. You cannot yet say what makes you hard to copy, or how you actually get from here to where you want to be. Everything feels equally urgent because nothing has been put in order."}, {"level": "Needs Attention", "range_max": 55, "range_min": 36, "description": "You have a picture of where this is going, but it is fuzzy, and your goals are either too big or impossible to measure. You have not worked out what makes you hard to copy. How you will fund this is decided as you go. You say yes to too much, because you have not decided what you are really aiming at."}, {"level": "Developing", "range_max": 75, "range_min": 56, "description": "You know where you are going, your goals are realistic, and you have some way of choosing between options. You understand where you sit against others reasonably well. There is some thinking behind how you fund this. You can say what success looks like a year from now."}, {"level": "Strong", "range_max": 100, "range_min": 76, "description": "You think and act with a clear plan. You have a picture worth chasing, goals you can measure, a clear view of what makes you hard to copy, and a funding plan tied to what you are actually reaching. You say no without agonising. You think through what-ifs, and you change the plan when the facts change."}]', '[{"stage": "Ideation (Stage 1)", "stage_id": 1, "description": "Strategic Clarity is mostly about idea conviction and initial market hypothesis. Low scores are expected. The signal is whether the founder has thought about why their timing is right and what makes them the right person.", "stage_group": "Stage 0"}, {"stage": "Validation to Prototype/MVP (Stages 2-3)", "stage_id": "2-3", "description": "Milestone clarity and early prioritisation. The founder must be able to articulate what they need to prove in the next 90 days and why that matters for the company''s survival and growth.", "stage_group": "Stage 0→1"}, {"stage": "Early Traction to Growth/Scaling (Stages 4-5)", "stage_id": "4-5", "description": "Competitive positioning and capital strategy become critical. The founder must know where they are playing, where they are not playing, and how they will defend their position as competition increases.", "stage_group": "Spans Stage 0→1 and Stage 1→10+"}, {"stage": "Expansion to Maturity (Stages 6-7)", "stage_id": "6-7", "description": "Portfolio thinking and organisational strategy. The founder must balance the demands of the current core business with the need to innovate and build for the future simultaneously.", "stage_group": "Stage 1→10+"}, {"stage": "Exit (Stage 8)", "stage_id": 8, "description": "Category creation and long-term institutional strategy. The founder is now setting direction for an organisation, not just a product.", "stage_group": "Stage 1→10+"}]', '2026-07-26 05:27:23.650751+00', '["Vision clarity — can the founder articulate where they are going and why it matters", "Goal quality — are goals specific, measurable, realistic, and time-bound", "Decision-making frameworks — does the founder have principles that guide hard choices", "Competitive strategy — do they know how they will win and sustain their advantage", "Capital strategy — do they know when to raise, how much, and from whom", "Prioritisation — can they say no to good opportunities to focus on great ones", "Scenario planning — have they thought about what happens if key assumptions are wrong", "Milestones — are there clear markers that tell them if the strategy is working"]') on conflict do nothing;
